#!/usr/bin/env python3
"""ROUTE1 analysis (planned/ROUTE1_PREREG.md). DIRECT plan-sharing rows are CAPACITY1's stored k = 1 rows."""
import json, glob, statistics as st
rd = lambda p: [json.loads(l) for f in glob.glob(p) for l in open(f) if l.strip()]
R = rd('out/route1/*.jsonl'); N = [r for r in R if r['part'] == 'n']
C = [r for r in R if r['part'] == 'c'] + [dict(r, arm='DIRECT') for r in rd('out/capacity1/c_*.jsonl') if r['axis'] == 'k' and r['x'] == 1 and (r['heights'], r['vol']) in (('A2', 'N2'), ('G1', 'V135'))]
M, OPS, ARMS, LAY = ('houston', 'dfw'), ('wing', 'zipline', 'amazon'), ('DIRECT', 'GATE1', 'GATE4'), (('A2', 'N2'), ('G1', 'V135'))
nx = lambda m, a: sorted([r for r in N if r['metro'] == m and r['arm'] == a], key=lambda r: r['seed'])
cx = lambda m, a, h, v: [r for r in C if r['metro'] == m and r['arm'] == a and r['heights'] == h and r['vol'] == v and r['seed'] <= 3]
def held(rows, op='all'):
    n = sum(r['cost'][op]['n'] for r in rows); return 100 * sum(r['cost'][op]['delayed'] + r['cost'][op]['cancelled'] for r in rows) / n if n else float('nan')
med = lambda xs: st.median(xs)
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
chk('R1', all(med([r['busiest'] for r in nx(m, 'GATE1')]) >= 1.5 * med([r['busiest'] for r in nx(m, 'DIRECT')]) for m in M), '; '.join(f'{m} busiest GATE1 {med([r["busiest"] for r in nx(m, "GATE1")]):.0f} vs DIRECT {med([r["busiest"] for r in nx(m, "DIRECT")]):.0f}' for m in M))
chk('R2', all(r['ge']['1150'] >= 1 for m in M for r in nx(m, 'GATE1')), '; '.join(f'{m} GATE1 receivers >= 1,150 by seed {[r["ge"]["1150"] for r in nx(m, "GATE1")]}' for m in M))
chk('R3', all(r['ge']['2300'] == 0 for r in N), '; '.join(f'{m} {a} >= 2,300 {[r["ge"]["2300"] for r in nx(m, a)]}' for m in M for a in ARMS))
chk('R4', all(sum(r['ge']['500'] for r in nx(m, 'GATE4')) < sum(r['ge']['500'] for r in nx(m, 'GATE1')) for m in M), '; '.join(f'{m} receivers >= 500 GATE1 {sum(r["ge"]["500"] for r in nx(m, "GATE1"))} GATE4 {sum(r["ge"]["500"] for r in nx(m, "GATE4"))} DIRECT {sum(r["ge"]["500"] for r in nx(m, "DIRECT"))}' for m in M))
p100 = lambda m, a: sum(r['pop100'] for r in nx(m, a))
chk('R5', all(p100(m, 'GATE1') <= 0.8 * p100(m, 'DIRECT') for m in M), '; '.join(f'{m} people at >= 100/day DIRECT {p100(m, "DIRECT")} GATE1 {p100(m, "GATE1")} ({100 * (p100(m, "GATE1") / p100(m, "DIRECT") - 1):+.0f} %) GATE4 {p100(m, "GATE4")}' for m in M))
km = lambda m, a: sum(r['allKm'] for r in nx(m, a)) / len(nx(m, a))
chk('R6', all(0.10 <= km(m, 'GATE1') / km(m, 'DIRECT') - 1 <= 0.40 and km(m, 'GATE4') / km(m, 'DIRECT') - 1 < 0.10 for m in M), '; '.join(f'{m} mean km per flight DIRECT {km(m, "DIRECT"):.2f}, GATE1 {100 * (km(m, "GATE1") / km(m, "DIRECT") - 1):+.1f} %, GATE4 {100 * (km(m, "GATE4") / km(m, "DIRECT") - 1):+.1f} %' for m in M))
chk('R7', all(abs(held(cx(m, a, h, v)) - held(cx(m, 'DIRECT', h, v))) <= 2 for m in M for a in ('GATE1', 'GATE4') for h, v in LAY), '; '.join(f'{m} {h}/{v} DIRECT {held(cx(m, "DIRECT", h, v)):.1f} GATE1 {held(cx(m, "GATE1", h, v)):.1f} GATE4 {held(cx(m, "GATE4", h, v)):.1f}' for m in M for h, v in LAY))
chk('R8', all(max(OPS, key=lambda op: held(cx(m, a, 'A2', 'N2'), op)) == 'amazon' for m in M for a in ARMS), '; '.join(f'{m} {a} Amazon {held(cx(m, a, "A2", "N2"), "amazon"):.1f} %' for m in M for a in ARMS))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# ROUTE1 results table (generated by planned/route1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Rows: {len(R)} (+ CAPACITY1 k = 1 DIRECT rows).', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Overflights, noise and distance (filed volumes; seeds 1-3; sums or means as marked)', '', '| Metro | Arm | Busiest receiver (median) | >= 500 (sum) | >= 1,150 (sum) | >= 2,300 (sum) | People >= 100/day (sum) | People >= 50/day (sum) | Max en route DNL (median) | Mean km per flight | Wing / Zipline / Amazon km | Flights using a gate |', '|---|---|---|---|---|---|---|---|---|---|---|---|']
for m in M:
    for a in ARMS:
        x = nx(m, a)
        if not x: continue
        L.append(f'| {m} | {a} | {med([r["busiest"] for r in x]):.0f} | {sum(r["ge"]["500"] for r in x)} | {sum(r["ge"]["1150"] for r in x)} | {sum(r["ge"]["2300"] for r in x)} | {sum(r["pop100"] for r in x)} | {sum(r["pop50"] for r in x)} | {med([r["dnlMax"] for r in x]):.1f} | {km(m, a):.2f} | ' + ' / '.join(f'{sum(r["distKm"][op] for r in x) / len(x):.2f}' for op in OPS) + f' | {100 * sum(r["gateUsed"] for r in x) / sum(r["n"] for r in x):.0f} % |')
L += ['', '## Plan sharing at filed volume (held share %, seeds 1-3; all / Wing / Zipline / Amazon; cancelled)', '', '| Metro | Layout | Arm | All | Wing | Zipline | Amazon | Cancelled |', '|---|---|---|---|---|---|---|---|']
for m in M:
    for h, v in LAY:
        for a in ARMS:
            x = cx(m, a, h, v)
            if not x: continue
            L.append(f'| {m} | {h} / {v} | {a} | ' + ' | '.join(f'{held(x, op):.1f}' for op in ('all',) + OPS) + f' | {sum(r["cost"]["all"]["cancelled"] for r in x)} |')
open('planned/route1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
